ALTER TABLE public.profiles ADD COLUMN account_status text NOT NULL DEFAULT 'active' CHECK (account_status IN ('active','paused'));
CREATE POLICY "admin profiles update" ON public.profiles FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.protect_account_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.account_status IS DISTINCT FROM OLD.account_status AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_account_status BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_account_status();
CREATE TABLE public.course_lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.courses(id), title text NOT NULL, position integer NOT NULL DEFAULT 1 CHECK (position>0), video_url text NOT NULL DEFAULT '', resource_path text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.course_lessons TO authenticated; GRANT ALL ON public.course_lessons TO service_role; ALTER TABLE public.course_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin lessons all" ON public.course_lessons FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "enrolled lessons read" ON public.course_lessons FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.enrollments e WHERE e.user_id=auth.uid() AND e.course_id=course_lessons.course_id::text));
CREATE TABLE public.class_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,kind text NOT NULL DEFAULT 'class' CHECK(kind IN ('class','webinar')),starts_at timestamptz NOT NULL, youtube_url text NOT NULL DEFAULT '',jitsi_url text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.class_sessions TO authenticated; GRANT SELECT ON public.class_sessions TO anon; GRANT ALL ON public.class_sessions TO service_role; ALTER TABLE public.class_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin sessions all" ON public.class_sessions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "scheduled sessions read" ON public.class_sessions FOR SELECT TO anon,authenticated USING(status='scheduled');
CREATE TABLE public.ebooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,price integer NOT NULL DEFAULT 0 CHECK(price>=0),resource_path text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ebooks TO authenticated; GRANT ALL ON public.ebooks TO service_role; ALTER TABLE public.ebooks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin ebooks all" ON public.ebooks FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,course_id text NOT NULL,amount integer NOT NULL CHECK(amount>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded')),provider_reference text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "orders read" ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.referral_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),referrer_id uuid NOT NULL,referred_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),CHECK(referrer_id<>referred_id));
GRANT SELECT ON public.referral_relationships TO authenticated; GRANT ALL ON public.referral_relationships TO service_role; ALTER TABLE public.referral_relationships ENABLE ROW LEVEL SECURITY;
CREATE POLICY "referrals read" ON public.referral_relationships FOR SELECT TO authenticated USING(referrer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.commission_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE REFERENCES public.orders(id),amount integer NOT NULL CHECK(amount>0),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commission_entries TO authenticated; GRANT ALL ON public.commission_entries TO service_role; ALTER TABLE public.commission_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "commissions read" ON public.commission_entries FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_sale_commission() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=NEW.order_id AND status='paid' AND amount>0 AND provider_reference IS NOT NULL AND amount>=NEW.amount) THEN RAISE EXCEPTION 'Commission requires a verified genuine sale'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_sale_commission BEFORE INSERT OR UPDATE ON public.commission_entries FOR EACH ROW EXECUTE FUNCTION public.validate_sale_commission();
CREATE TABLE public.payout_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,amount integer NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewed','rejected','paid')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.payout_requests TO authenticated; GRANT ALL ON public.payout_requests TO service_role; ALTER TABLE public.payout_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "payouts read" ON public.payout_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "admin payout review" ON public.payout_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') AND status<>'paid') WITH CHECK(public.has_role(auth.uid(),'admin') AND status IN ('reviewed','rejected'));
CREATE TABLE public.admin_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),support_email text NOT NULL DEFAULT '',support_phone text NOT NULL DEFAULT '',commission_percent integer NOT NULL DEFAULT 0 CHECK(commission_percent BETWEEN 0 AND 100),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.admin_settings TO authenticated; GRANT ALL ON public.admin_settings TO service_role; ALTER TABLE public.admin_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin settings all" ON public.admin_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,resource text NOT NULL,record_id uuid,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit_log TO authenticated; GRANT ALL ON public.admin_audit_log TO service_role; ALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "admin audit read" ON public.admin_audit_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_admin_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.admin_audit_log(actor_id,resource,record_id,action) VALUES(auth.uid(),TG_TABLE_NAME,COALESCE(NEW.id,OLD.id),TG_OP); RETURN COALESCE(NEW,OLD); END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['courses','course_lessons','class_sessions','ebooks','demo_bookings','profiles','notification_campaigns','payout_requests','admin_settings'] LOOP EXECUTE format('CREATE TRIGGER audit_change AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change()',t); END LOOP; END $$;
DROP POLICY "published campaigns read" ON public.notification_campaigns;
CREATE TABLE public.user_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,campaign_id uuid NOT NULL REFERENCES public.notification_campaigns(id),read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,campaign_id));
GRANT SELECT,UPDATE ON public.user_notifications TO authenticated; GRANT ALL ON public.user_notifications TO service_role; ALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own notifications read" ON public.user_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "own notifications update" ON public.user_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY "recipient campaigns read" ON public.notification_campaigns FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_notifications n WHERE n.user_id=auth.uid() AND n.campaign_id=notification_campaigns.id));
CREATE FUNCTION public.deliver_in_app_campaign() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='published' AND (TG_OP='INSERT' OR OLD.status<>'published') THEN INSERT INTO public.user_notifications(user_id,campaign_id) SELECT p.id,NEW.id FROM public.profiles p WHERE p.account_status='active' AND (NEW.audience='all' OR NEW.audience='city:'||COALESCE(p.city,'') OR NEW.audience='state:'||COALESCE(p.state,'') OR NEW.audience='user:'||p.id::text OR EXISTS(SELECT 1 FROM public.enrollments e WHERE e.user_id=p.id AND NEW.audience='course:'||e.course_id)) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER deliver_in_app_campaign AFTER INSERT OR UPDATE ON public.notification_campaigns FOR EACH ROW EXECUTE FUNCTION public.deliver_in_app_campaign();
CREATE POLICY "admin resources read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='course-resources' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "admin resources upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='course-resources' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "admin resources delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='course-resources' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "enrolled resources read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='course-resources' AND EXISTS(SELECT 1 FROM public.course_lessons l JOIN public.enrollments e ON e.course_id=l.course_id::text WHERE l.resource_path=storage.objects.name AND e.user_id=auth.uid()));